CREATE TABLE roles(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(50) UNIQUE NOT NULL);
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(80) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE user_roles(user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE departments(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL);
CREATE TABLE patients(id BIGINT PRIMARY KEY AUTO_INCREMENT,uhid VARCHAR(40) UNIQUE NOT NULL,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80),gender VARCHAR(20),dob DATE,mobile VARCHAR(20),blood_group VARCHAR(10),address VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments(id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT NOT NULL,department_id BIGINT,doctor_name VARCHAR(120),appointment_at DATETIME NOT NULL,type VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,reason VARCHAR(500),FOREIGN KEY(patient_id) REFERENCES patients(id),FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE encounters(id BIGINT PRIMARY KEY AUTO_INCREMENT,encounter_no VARCHAR(40) UNIQUE NOT NULL,patient_id BIGINT NOT NULL,appointment_id BIGINT UNIQUE,department_id BIGINT,doctor_name VARCHAR(120),encounter_type VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,chief_complaint VARCHAR(1000),started_at DATETIME DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME,FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE vitals(id BIGINT PRIMARY KEY AUTO_INCREMENT,encounter_id BIGINT NOT NULL,temperature DECIMAL(5,2),pulse INT,systolic INT,diastolic INT,spo2 DECIMAL(5,2),weight_kg DECIMAL(7,2),height_cm DECIMAL(7,2),recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(encounter_id) REFERENCES encounters(id));
CREATE TABLE consultations(id BIGINT PRIMARY KEY AUTO_INCREMENT,encounter_id BIGINT NOT NULL,history TEXT,examination TEXT,diagnosis TEXT,advice TEXT,follow_up_date DATE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(encounter_id) REFERENCES encounters(id));
CREATE TABLE lab_test_catalog(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,sample_type VARCHAR(60),default_processing_type VARCHAR(20) NOT NULL,price DECIMAL(12,2) NOT NULL,active BOOLEAN DEFAULT TRUE);
CREATE TABLE external_labs(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) NOT NULL,contact VARCHAR(100),address VARCHAR(500),active BOOLEAN DEFAULT TRUE);
CREATE TABLE lab_orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(40) UNIQUE NOT NULL,encounter_id BIGINT NOT NULL,patient_id BIGINT NOT NULL,status VARCHAR(30) NOT NULL,ordered_by VARCHAR(120),ordered_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(encounter_id) REFERENCES encounters(id),FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE lab_order_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,lab_order_id BIGINT NOT NULL,test_code VARCHAR(40) NOT NULL,test_name VARCHAR(150) NOT NULL,processing_type VARCHAR(20) NOT NULL,external_lab_id BIGINT,status VARCHAR(30) NOT NULL,result_value VARCHAR(500),result_unit VARCHAR(50),reference_range VARCHAR(100),verified_by VARCHAR(120),verified_at DATETIME,FOREIGN KEY(lab_order_id) REFERENCES lab_orders(id));
CREATE TABLE lab_samples(id BIGINT PRIMARY KEY AUTO_INCREMENT,sample_id VARCHAR(50) UNIQUE NOT NULL,lab_order_id BIGINT NOT NULL,sample_type VARCHAR(60),collected_by VARCHAR(120),collected_at DATETIME,status VARCHAR(30),FOREIGN KEY(lab_order_id) REFERENCES lab_orders(id));
CREATE TABLE sample_dispatches(id BIGINT PRIMARY KEY AUTO_INCREMENT,lab_order_item_id BIGINT NOT NULL,external_lab_id BIGINT,sample_id VARCHAR(50),courier_details VARCHAR(255),tracking_number VARCHAR(100),dispatch_time DATETIME,received_time DATETIME,status VARCHAR(30),FOREIGN KEY(lab_order_item_id) REFERENCES lab_order_items(id));
CREATE TABLE invoices(id BIGINT PRIMARY KEY AUTO_INCREMENT,invoice_no VARCHAR(40) UNIQUE NOT NULL,patient_id BIGINT NOT NULL,encounter_id BIGINT,total DECIMAL(12,2) NOT NULL DEFAULT 0,paid DECIMAL(12,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoice_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT NOT NULL,item_type VARCHAR(40),reference_id BIGINT,description VARCHAR(255),qty DECIMAL(10,2),unit_price DECIMAL(12,2),amount DECIMAL(12,2),FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE payments(id BIGINT PRIMARY KEY AUTO_INCREMENT,invoice_id BIGINT NOT NULL,amount DECIMAL(12,2) NOT NULL,method VARCHAR(30),reference_no VARCHAR(100),paid_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE prescriptions(id BIGINT PRIMARY KEY AUTO_INCREMENT,encounter_id BIGINT NOT NULL,patient_id BIGINT NOT NULL,status VARCHAR(30),created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE prescription_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,prescription_id BIGINT NOT NULL,medicine_name VARCHAR(150),dose VARCHAR(80),frequency VARCHAR(80),duration VARCHAR(80),instructions VARCHAR(255),FOREIGN KEY(prescription_id) REFERENCES prescriptions(id));
CREATE TABLE radiology_orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(40) UNIQUE NOT NULL,encounter_id BIGINT,patient_id BIGINT,study_name VARCHAR(150),status VARCHAR(30),report TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admissions(id BIGINT PRIMARY KEY AUTO_INCREMENT,admission_no VARCHAR(40) UNIQUE NOT NULL,encounter_id BIGINT,patient_id BIGINT,ward VARCHAR(80),bed_no VARCHAR(30),status VARCHAR(30),admitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,discharged_at DATETIME);
CREATE TABLE inventory_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,sku VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(150),category VARCHAR(80),stock_qty DECIMAL(12,2) DEFAULT 0,reorder_level DECIMAL(12,2) DEFAULT 0,unit VARCHAR(30));
CREATE TABLE insurance_claims(id BIGINT PRIMARY KEY AUTO_INCREMENT,patient_id BIGINT,encounter_id BIGINT,provider VARCHAR(150),policy_no VARCHAR(100),claim_amount DECIMAL(12,2),approved_amount DECIMAL(12,2),status VARCHAR(30));
CREATE TABLE employees(id BIGINT PRIMARY KEY AUTO_INCREMENT,employee_no VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(150),department VARCHAR(100),designation VARCHAR(100),mobile VARCHAR(20),status VARCHAR(30));
CREATE TABLE audit_logs(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(80),action VARCHAR(100),entity_type VARCHAR(80),entity_id VARCHAR(80),details TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
